contracts/Compliance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/ICompliance.sol";
import "./interfaces/IIdentityRegistry.sol";

/**
 * @title Compliance
 * @dev Manages jurisdictional compliance rules, transfer restrictions, and audit reporting
 * Integrates with Integra's policy-based privacy and regulatory frameworks
 */
contract Compliance is AccessControl, ReentrancyGuard, ICompliance {

    // Roles
    bytes32 public constant COMPLIANCE_OFFICER_ROLE = keccak256("COMPLIANCE_OFFICER_ROLE");
    bytes32 public constant RULE_MANAGER_ROLE = keccak256("RULE_MANAGER_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");

    // Compliance rule types
    bytes32 public constant TRANSFER_LIMIT_RULE = keccak256("TRANSFER_LIMIT_RULE");
    bytes32 public constant COUNTRY_RESTRICTION_RULE = keccak256("COUNTRY_RESTRICTION_RULE");
    bytes32 public constant INVESTOR_TYPE_RULE = keccak256("INVESTOR_TYPE_RULE");
    bytes32 public constant TIME_LOCK_RULE = keccak256("TIME_LOCK_RULE");
    bytes32 public constant KYC_REQUIREMENT_RULE = keccak256("KYC_REQUIREMENT_RULE");
    bytes32 public constant HOLDING_PERIOD_RULE = keccak256("HOLDING_PERIOD_RULE");

    // Investor types for compliance
    enum InvestorType {
        RETAIL,
        ACCREDITED,
        INSTITUTIONAL,
        QUALIFIED
    }

    // Compliance rule structure
    struct ComplianceRule {
        bytes32 ruleType;
        address ruleAddress;        // External rule contract
        bool isActive;
        uint256 priority;          // Higher number = higher priority
        string description;
        bytes32 configHash;        // Hash of rule configuration
        uint256 createdAt;
        uint256 lastModified;
    }

    // Transfer restriction structure
    struct TransferRestriction {
        uint16 fromCountry;        // Source country (0 = any)
        uint16 toCountry;          // Destination country (0 = any)
        InvestorType fromType;     // Source investor type
        InvestorType toType;       // Destination investor type
        uint256 minAmount;         // Minimum transfer amount
        uint256 maxAmount;         // Maximum transfer amount
        uint256 dailyLimit;        // Daily transfer limit
        uint256 monthlyLimit;      // Monthly transfer limit
        bool isBlocked;            // Complete block
        string reason;             // Restriction reason
    }

    // Holding period requirement
    struct HoldingPeriod {
        address investor;
        uint256 amount;
        uint256 acquisitionDate;
        uint256 minimumHoldPeriod;
        bool isLocked;
    }

    // Audit trail entry
    struct AuditEntry {
        uint256 timestamp;
        address user;
        string action;
        bytes32 dataHash;
        bool isCompliant;
        string details;
    }

    // Storage mappings
    mapping(address => bool) private _boundTokens;
    mapping(bytes32 => ComplianceRule[]) private _rules;
    mapping(address => mapping(address => uint256)) private _dailyTransfers;   // user => token => amount
    mapping(address => mapping(address => uint256)) private _monthlyTransfers; // user => token => amount
    mapping(address => mapping(address => uint256)) private _lastTransferDate; // user => token => date
    mapping(address => InvestorType) public investorTypes;
    mapping(bytes32 => bool) public restrictedCountryPairs; // hash(fromCountry, toCountry) => blocked
    mapping(address => HoldingPeriod[]) public investorHoldings;
    mapping(uint256 => TransferRestriction) public transferRestrictions;

    // Audit trail
    AuditEntry[] public auditTrail;
    mapping(address => uint256[]) public userAuditHistory; // user => audit indices

    // Contract references
    IIdentityRegistry public identityRegistry;

    // Configuration
    uint256 public defaultHoldingPeriod = 365 days;
    uint256 public maxTransferAmount = 1000000 * 10**18; // 1M tokens
    uint256 public maxDailyTransfers = 10;
    bool public globalTransfersPaused = false;

    // Counters
    uint256 private _restrictionCounter;

    constructor(address _identityRegistry) {
        require(_identityRegistry != address(0), "Compliance: invalid identity registry");

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(COMPLIANCE_OFFICER_ROLE, msg.sender);
        _grantRole(RULE_MANAGER_ROLE, msg.sender);
        _grantRole(AUDITOR_ROLE, msg.sender);

        identityRegistry = IIdentityRegistry(_identityRegistry);

        _addAuditEntry(msg.sender, "CONTRACT_DEPLOYED", bytes32(0), true, "Compliance contract deployed");
    }

    // Modifiers
    modifier onlyComplianceOfficer() {
        require(hasRole(COMPLIANCE_OFFICER_ROLE, msg.sender), "Compliance: not compliance officer");
        _;
    }

    modifier onlyRuleManager() {
        require(hasRole(RULE_MANAGER_ROLE, msg.sender), "Compliance: not rule manager");
        _;
    }

    modifier onlyAuditor() {
        require(hasRole(AUDITOR_ROLE, msg.sender), "Compliance: not auditor");
        _;
    }

    modifier onlyBoundToken() {
        require(_boundTokens[msg.sender], "Compliance: token not bound");
        _;
    }

    // Core Compliance Functions (ICompliance implementation)

    /**
     * @dev Check if transfer is compliant with all rules
     */
    function canTransfer(address _from, address _to, uint256 _amount) 
        external 
        view 
        override 
        returns (bool) 
    {
        if (globalTransfersPaused) return false;

        // Basic identity verification
        if (!identityRegistry.isVerified(_from) || !identityRegistry.isVerified(_to)) {
            return false;
        }

        // Check country restrictions
        uint16 fromCountry = identityRegistry.investorCountry(_from);
        uint16 toCountry = identityRegistry.investorCountry(_to);
        bytes32 countryPairHash = keccak256(abi.encodePacked(fromCountry, toCountry));
        if (restrictedCountryPairs[countryPairHash]) {
            return false;
        }

        // Check investor type restrictions
        InvestorType fromType = investorTypes[_from];
        InvestorType toType = investorTypes[_to];

        // Check amount limits
        if (_amount > maxTransferAmount) return false;

        // Check daily transfer limits
        uint256 dailyTotal = _dailyTransfers[_from][msg.sender];
        if (dailyTotal + _amount > maxTransferAmount) return false;

        // Check holding periods
        if (!_checkHoldingPeriod(_from, _amount)) return false;

        // Execute rule-based checks
        return _executeRuleChecks(_from, _to, _amount);
    }

    /**
     * @dev Called after successful transfer to update state
     */
    function transferred(address _from, address _to, uint256 _amount) 
        external 
        override 
        onlyBoundToken 
    {
        // Update transfer counters
        _updateTransferCounters(_from, _amount);

        // Update holding periods
        _updateHoldingPeriods(_from, _to, _amount);

        // Log audit entry
        _addAuditEntry(
            _from, 
            "TRANSFER_EXECUTED", 
            keccak256(abi.encodePacked(_from, _to, _amount)), 
            true, 
            string(abi.encodePacked("Transferred ", _uint2str(_amount), " to ", _addressToString(_to)))
        );
    }

    /**
     * @dev Called after token creation/minting
     */
    function created(address _to, uint256 _amount) 
        external 
        override 
        onlyBoundToken 
    {
        // Add new holding period for minted tokens
        investorHoldings[_to].push(HoldingPeriod({
            investor: _to,
            amount: _amount,
            acquisitionDate: block.timestamp,
            minimumHoldPeriod: defaultHoldingPeriod,
            isLocked: true
        }));

        _addAuditEntry(
            _to, 
            "TOKENS_CREATED", 
            keccak256(abi.encodePacked(_to, _amount)), 
            true, 
            string(abi.encodePacked("Created ", _uint2str(_amount), " tokens"))
        );
    }

    /**
     * @dev Called after token destruction/burning
     */
    function destroyed(address _from, uint256 _amount) 
        external 
        override 
        onlyBoundToken 
    {
        // Remove holding periods for burned tokens
        _removeHoldingPeriods(_from, _amount);

        _addAuditEntry(
            _from, 
            "TOKENS_DESTROYED", 
            keccak256(abi.encodePacked(_from, _amount)), 
            true, 
            string(abi.encodePacked("Destroyed ", _uint2str(_amount), " tokens"))
        );
    }

    // Token Binding Functions

    /**
     * @dev Bind compliance to token contract
     */
    function bindToken(address _token) 
        external 
        override 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        require(_token != address(0), "Compliance: invalid token address");
        _boundTokens[_token] = true;

        emit TokenBound(_token);
        _addAuditEntry(msg.sender, "TOKEN_BOUND", bytes32(uint256(uint160(_token))), true, "Token bound to compliance");
    }

    /**
     * @dev Unbind compliance from token contract
     */
    function unbindToken(address _token) 
        external 
        override 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        _boundTokens[_token] = false;

        emit TokenUnbound(_token);
        _addAuditEntry(msg.sender, "TOKEN_UNBOUND", bytes32(uint256(uint160(_token))), true, "Token unbound from compliance");
    }

    /**
     * @dev Check if token is bound
     */
    function isTokenBound(address _token) 
        external 
        view 
        override 
        returns (bool) 
    {
        return _boundTokens[_token];
    }

    // Rule Management Functions

    /**
     * @dev Add compliance rule
     */
    function addRule(bytes32 _ruleType, address _ruleAddress) 
        external 
        override 
        onlyRuleManager 
    {
        require(_ruleAddress != address(0), "Compliance: invalid rule address");

        _rules[_ruleType].push(ComplianceRule({
            ruleType: _ruleType,
            ruleAddress: _ruleAddress,
            isActive: true,
            priority: 100, // Default priority
            description: "",
            configHash: bytes32(0),
            createdAt: block.timestamp,
            lastModified: block.timestamp
        }));

        emit RuleAdded(_ruleType, _ruleAddress);
        _addAuditEntry(msg.sender, "RULE_ADDED", _ruleType, true, "New compliance rule added");
    }

    /**
     * @dev Remove compliance rule
     */
    function removeRule(bytes32 _ruleType, address _ruleAddress) 
        external 
        override 
        onlyRuleManager 
    {
        ComplianceRule[] storage rules = _rules[_ruleType];

        for (uint256 i = 0; i < rules.length; i++) {
            if (rules[i].ruleAddress == _ruleAddress) {
                rules[i] = rules[rules.length - 1];
                rules.pop();
                break;
            }
        }

        emit RuleRemoved(_ruleType, _ruleAddress);
        _addAuditEntry(msg.sender, "RULE_REMOVED", _ruleType, true, "Compliance rule removed");
    }

    /**
     * @dev Get rules for type
     */
    function getRules(bytes32 _ruleType) 
        external 
        view 
        override 
        returns (address[] memory) 
    {
        ComplianceRule[] memory rules = _rules[_ruleType];
        address[] memory ruleAddresses = new address[](rules.length);

        for (uint256 i = 0; i < rules.length; i++) {
            ruleAddresses[i] = rules[i].ruleAddress;
        }

        return ruleAddresses;
    }

    // Compliance Status Functions

    /**
     * @dev Get compliance status for user
     */
    function getComplianceStatus(address _user) 
        external 
        view 
        override 
        returns (bool) 
    {
        if (!identityRegistry.isVerified(_user)) return false;

        // Check if user has any active restrictions
        uint16 userCountry = identityRegistry.investorCountry(_user);
        InvestorType userType = investorTypes[_user];

        // Additional compliance checks can be added here
        return true;
    }

    /**
     * @dev Get transfer restrictions for user pair
     */
    function getTransferRestrictions(address _from, address _to) 
        external 
        view 
        override 
        returns (string[] memory) 
    {
        string[] memory restrictions = new string[](5);
        uint256 count = 0;

        if (!identityRegistry.isVerified(_from)) {
            restrictions[count++] = "Sender not verified";
        }

        if (!identityRegistry.isVerified(_to)) {
            restrictions[count++] = "Recipient not verified";
        }

        if (globalTransfersPaused) {
            restrictions[count++] = "Global transfers paused";
        }

        uint16 fromCountry = identityRegistry.investorCountry(_from);
        uint16 toCountry = identityRegistry.investorCountry(_to);
        bytes32 countryPairHash = keccak256(abi.encodePacked(fromCountry, toCountry));

        if (restrictedCountryPairs[countryPairHash]) {
            restrictions[count++] = "Country pair restricted";
        }

        if (!_checkHoldingPeriod(_from, 0)) {
            restrictions[count++] = "Holding period not met";
        }

        // Resize array to actual count
        string[] memory result = new string[](count);
        for (uint256 i = 0; i < count; i++) {
            result[i] = restrictions[i];
        }

        return result;
    }

    // Administrative Functions

    /**
     * @dev Set investor type
     */
    function setInvestorType(address _investor, InvestorType _type) 
        external 
        onlyComplianceOfficer 
    {
        investorTypes[_investor] = _type;

        _addAuditEntry(
            _investor, 
            "INVESTOR_TYPE_SET", 
            bytes32(uint256(_type)), 
            true, 
            "Investor type updated"
        );
    }

    /**
     * @dev Set country pair restriction
     */
    function setCountryRestriction(uint16 _fromCountry, uint16 _toCountry, bool _restricted) 
        external 
        onlyComplianceOfficer 
    {
        bytes32 countryPairHash = keccak256(abi.encodePacked(_fromCountry, _toCountry));
        restrictedCountryPairs[countryPairHash] = _restricted;

        _addAuditEntry(
            msg.sender, 
            "COUNTRY_RESTRICTION_SET", 
            countryPairHash, 
            true, 
            _restricted ? "Country pair restricted" : "Country pair unrestricted"
        );
    }

    /**
     * @dev Update configuration
     */
    function updateConfiguration(
        uint256 _defaultHoldingPeriod,
        uint256 _maxTransferAmount,
        uint256 _maxDailyTransfers
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        defaultHoldingPeriod = _defaultHoldingPeriod;
        maxTransferAmount = _maxTransferAmount;
        maxDailyTransfers = _maxDailyTransfers;

        _addAuditEntry(msg.sender, "CONFIG_UPDATED", bytes32(0), true, "Configuration updated");
    }

    /**
     * @dev Pause/unpause global transfers
     */
    function setGlobalTransfersPaused(bool _paused) 
        external 
        onlyComplianceOfficer 
    {
        globalTransfersPaused = _paused;

        _addAuditEntry(
            msg.sender, 
            "GLOBAL_TRANSFERS_PAUSED", 
            bytes32(uint256(_paused ? 1 : 0)), 
            true, 
            _paused ? "Global transfers paused" : "Global transfers resumed"
        );
    }

    // Audit Functions

    /**
     * @dev Get audit trail
     */
    function getAuditTrail(uint256 _start, uint256 _limit) 
        external 
        view 
        onlyAuditor 
        returns (AuditEntry[] memory) 
    {
        require(_start < auditTrail.length, "Compliance: invalid start index");

        uint256 end = _start + _limit;
        if (end > auditTrail.length) {
            end = auditTrail.length;
        }

        AuditEntry[] memory entries = new AuditEntry[](end - _start);
        for (uint256 i = _start; i < end; i++) {
            entries[i - _start] = auditTrail[i];
        }

        return entries;
    }

    /**
     * @dev Get user audit history
     */
    function getUserAuditHistory(address _user) 
        external 
        view 
        onlyAuditor 
        returns (AuditEntry[] memory) 
    {
        uint256[] memory indices = userAuditHistory[_user];
        AuditEntry[] memory entries = new AuditEntry[](indices.length);

        for (uint256 i = 0; i < indices.length; i++) {
            entries[i] = auditTrail[indices[i]];
        }

        return entries;
    }

    /**
     * @dev Generate compliance report
     */
    function generateComplianceReport() 
        external 
        view 
        onlyAuditor 
        returns (
            uint256 totalAuditEntries,
            uint256 complianceViolations,
            uint256 boundTokens,
            uint256 activeRules,
            bool globalPaused
        ) 
    {
        uint256 violations = 0;
        for (uint256 i = 0; i < auditTrail.length; i++) {
            if (!auditTrail[i].isCompliant) violations++;
        }

        uint256 totalRules = 0;
        bytes32[6] memory ruleTypes = [
            TRANSFER_LIMIT_RULE,
            COUNTRY_RESTRICTION_RULE,
            INVESTOR_TYPE_RULE,
            TIME_LOCK_RULE,
            KYC_REQUIREMENT_RULE,
            HOLDING_PERIOD_RULE
        ];

        for (uint256 i = 0; i < ruleTypes.length; i++) {
            totalRules += _rules[ruleTypes[i]].length;
        }

        return (
            auditTrail.length,
            violations,
            0, // Would need to track this separately
            totalRules,
            globalTransfersPaused
        );
    }

    // Internal Functions

    /**
     * @dev Execute all rule checks
     */
    function _executeRuleChecks(address _from, address _to, uint256 _amount) 
        internal 
        view 
        returns (bool) 
    {
        // This would execute external rule contracts
        // For now, return true (implement rule contract calling logic)
        return true;
    }

    /**
     * @dev Check holding period compliance
     */
    function _checkHoldingPeriod(address _investor, uint256 _amount) 
        internal 
        view 
        returns (bool) 
    {
        HoldingPeriod[] memory holdings = investorHoldings[_investor];
        uint256 availableAmount = 0;

        for (uint256 i = 0; i < holdings.length; i++) {
            if (!holdings[i].isLocked || 
                block.timestamp >= holdings[i].acquisitionDate + holdings[i].minimumHoldPeriod) {
                availableAmount += holdings[i].amount;
            }
        }

        return availableAmount >= _amount;
    }

    /**
     * @dev Update transfer counters for limits
     */
    function _updateTransferCounters(address _from, uint256 _amount) internal {
        uint256 today = block.timestamp / 1 days;

        if (_lastTransferDate[_from][msg.sender] != today) {
            _dailyTransfers[_from][msg.sender] = 0;
            _lastTransferDate[_from][msg.sender] = today;
        }

        _dailyTransfers[_from][msg.sender] += _amount;

        uint256 thisMonth = block.timestamp / 30 days;
        _monthlyTransfers[_from][msg.sender] += _amount;
    }

    /**
     * @dev Update holding periods after transfer
     */
    function _updateHoldingPeriods(address _from, address _to, uint256 _amount) internal {
        // Remove from sender's holdings (FIFO)
        _removeHoldingPeriods(_from, _amount);

        // Add to recipient's holdings
        investorHoldings[_to].push(HoldingPeriod({
            investor: _to,
            amount: _amount,
            acquisitionDate: block.timestamp,
            minimumHoldPeriod: defaultHoldingPeriod,
            isLocked: true
        }));
    }

    /**
     * @dev Remove holding periods (FIFO basis)
     */
    function _removeHoldingPeriods(address _investor, uint256 _amount) internal {
        HoldingPeriod[] storage holdings = investorHoldings[_investor];
        uint256 remainingAmount = _amount;

        for (uint256 i = 0; i < holdings.length && remainingAmount > 0; i++) {
            if (holdings[i].amount <= remainingAmount) {
                remainingAmount -= holdings[i].amount;
                holdings[i] = holdings[holdings.length - 1];
                holdings.pop();
                i--; // Adjust index after removal
            } else {
                holdings[i].amount -= remainingAmount;
                remainingAmount = 0;
            }
        }
    }

    /**
     * @dev Add audit trail entry
     */
    function _addAuditEntry(
        address _user, 
        string memory _action, 
        bytes32 _dataHash, 
        bool _isCompliant, 
        string memory _details
    ) internal {
        auditTrail.push(AuditEntry({
            timestamp: block.timestamp,
            user: _user,
            action: _action,
            dataHash: _dataHash,
            isCompliant: _isCompliant,
            details: _details
        }));

        userAuditHistory[_user].push(auditTrail.length - 1);
    }

    // Utility functions
    function _uint2str(uint256 _i) internal pure returns (string memory) {
        if (_i == 0) return "0";
        uint256 j = _i;
        uint256 len;
        while (j != 0) {
            len++;
            j /= 10;
        }
        bytes memory bstr = new bytes(len);
        uint256 k = len;
        while (_i != 0) {
            k = k - 1;
            uint8 temp = (48 + uint8(_i - _i / 10 * 10));
            bytes1 b1 = bytes1(temp);
            bstr[k] = b1;
            _i /= 10;
        }
        return string(bstr);
    }

    function _addressToString(address _addr) internal pure returns (string memory) {
        bytes32 value = bytes32(uint256(uint160(_addr)));
        bytes memory alphabet = "0123456789abcdef";
        bytes memory str = new bytes(42);
        str[0] = '0';
        str[1] = 'x';
        for (uint256 i = 0; i < 20; i++) {
            str[2 + i * 2] = alphabet[uint8(value[i + 12] >> 4)];
            str[3 + i * 2] = alphabet[uint8(value[i + 12] & 0x0f)];
        }
        return string(str);
    }
}

contracts/EscrowPayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./interfaces/IIdentityRegistry.sol";

/**
 * @title EscrowPayment
 * @dev Manages security deposits, rent payments, and escrow functionality
 * Integrates with Integra's fiat payment rails and on-chain proof-of-payment
 */
contract EscrowPayment is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // Roles
    bytes32 public constant ESCROW_AGENT_ROLE = keccak256("ESCROW_AGENT_ROLE");
    bytes32 public constant PAYMENT_PROCESSOR_ROLE = keccak256("PAYMENT_PROCESSOR_ROLE");
    bytes32 public constant DISPUTE_RESOLVER_ROLE = keccak256("DISPUTE_RESOLVER_ROLE");

    // Escrow status enumeration
    enum EscrowStatus {
        CREATED,        // Escrow created, awaiting deposit
        FUNDED,         // Funds deposited in escrow
        RELEASED,       // Funds released to recipient
        REFUNDED,       // Funds refunded to depositor
        DISPUTED,       // Escrow under dispute
        EXPIRED         // Escrow expired
    }

    // Payment method enumeration
    enum PaymentMethod {
        CRYPTO,         // Direct crypto payment
        FIAT_BRIDGE,    // Fiat payment via Integra bridge
        HYBRID          // Combination of crypto and fiat
    }

    // Escrow structure for security deposits
    struct SecurityDepositEscrow {
        uint256 escrowId;
        uint256 leaseId;            // Associated lease agreement
        address landlord;           // Funds recipient
        address tenant;             // Funds depositor
        address paymentToken;       // ERC-20 token (USDC, IRL, etc.)
        uint256 amount;             // Deposit amount
        uint256 createdAt;          // Creation timestamp
        uint256 releaseDate;        // Earliest release date
        EscrowStatus status;        // Current status
        string releaseConditions;   // IPFS hash of release conditions
        bytes32 conditionsHash;     // Hash of conditions for verification
    }

    // Rent payment structure
    struct RentPayment {
        uint256 paymentId;
        uint256 leaseId;            // Associated lease
        address landlord;           // Payment recipient
        address tenant;             // Payment sender
        address paymentToken;       // Payment token
        uint256 amount;             // Payment amount
        uint256 dueDate;            // Payment due date
        uint256 paidDate;           // Actual payment date
        PaymentMethod method;       // Payment method used
        string fiatReference;       // Fiat payment reference (if applicable)
        bytes32 proofHash;          // Hash of payment proof
        bool isAutomated;           // Whether payment was automated
    }

    // Automated payment subscription
    struct PaymentSubscription {
        uint256 subscriptionId;
        uint256 leaseId;
        address tenant;
        address landlord;
        address paymentToken;
        uint256 amount;             // Monthly payment amount
        uint256 startDate;          // Subscription start
        uint256 endDate;            // Subscription end
        uint256 lastPayment;        // Last successful payment
        uint256 nextPayment;        // Next scheduled payment
        bool isActive;              // Subscription status
        uint256 failedPayments;     // Failed payment counter
    }

    // Storage mappings
    mapping(uint256 => SecurityDepositEscrow) public securityDeposits;
    mapping(uint256 => RentPayment) public rentPayments;
    mapping(uint256 => PaymentSubscription) public paymentSubscriptions;
    mapping(uint256 => uint256) public leaseToEscrow;           // leaseId => escrowId
    mapping(uint256 => uint256) public leaseToSubscription;     // leaseId => subscriptionId
    mapping(address => bool) public approvedTokens;
    mapping(address => uint256[]) public landlordEscrows;
    mapping(address => uint256[]) public tenantEscrows;

    // Counters
    uint256 private _escrowCounter;
    uint256 private _paymentCounter;
    uint256 private _subscriptionCounter;

    // Contract references
    IIdentityRegistry public identityRegistry;
    address public leaseAgreementContract;
    address public fiatBridge;                  // Integra fiat bridge contract

    // Configuration
    uint256 public defaultEscrowPeriod = 365 days;
    uint256 public maxEscrowPeriod = 5 * 365 days;
    uint256 public automatedPaymentGracePeriod = 3 days;
    uint256 public maxFailedPayments = 3;

    // Events
    event SecurityDepositCreated(
        uint256 indexed escrowId,
        uint256 indexed leaseId,
        address indexed tenant,
        address landlord,
        uint256 amount
    );

    event SecurityDepositFunded(
        uint256 indexed escrowId,
        address indexed tenant,
        uint256 amount
    );

    event SecurityDepositReleased(
        uint256 indexed escrowId,
        address indexed recipient,
        uint256 amount,
        string reason
    );

    event RentPaymentProcessed(
        uint256 indexed paymentId,
        uint256 indexed leaseId,
        address indexed tenant,
        address landlord,
        uint256 amount,
        PaymentMethod method
    );

    event PaymentSubscriptionCreated(
        uint256 indexed subscriptionId,
        uint256 indexed leaseId,
        address indexed tenant,
        uint256 amount
    );

    event AutomatedPaymentExecuted(
        uint256 indexed subscriptionId,
        uint256 indexed paymentId,
        uint256 amount
    );

    event AutomatedPaymentFailed(
        uint256 indexed subscriptionId,
        uint256 failureCount,
        string reason
    );

    event DisputeRaised(
        uint256 indexed escrowId,
        address indexed raisedBy,
        string reason
    );

    constructor(
        address _identityRegistry,
        address _leaseAgreementContract
    ) {
        require(_identityRegistry != address(0), "EscrowPayment: invalid identity registry");
        require(_leaseAgreementContract != address(0), "EscrowPayment: invalid lease contract");

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ESCROW_AGENT_ROLE, msg.sender);
        _grantRole(PAYMENT_PROCESSOR_ROLE, msg.sender);
        _grantRole(DISPUTE_RESOLVER_ROLE, msg.sender);

        identityRegistry = IIdentityRegistry(_identityRegistry);
        leaseAgreementContract = _leaseAgreementContract;
    }

    // Modifiers
    modifier onlyEscrowAgent() {
        require(hasRole(ESCROW_AGENT_ROLE, msg.sender), "EscrowPayment: not an escrow agent");
        _;
    }

    modifier onlyPaymentProcessor() {
        require(hasRole(PAYMENT_PROCESSOR_ROLE, msg.sender), "EscrowPayment: not payment processor");
        _;
    }

    modifier onlyDisputeResolver() {
        require(hasRole(DISPUTE_RESOLVER_ROLE, msg.sender), "EscrowPayment: not dispute resolver");
        _;
    }

    modifier validEscrow(uint256 _escrowId) {
        require(_escrowId > 0 && _escrowId <= _escrowCounter, "EscrowPayment: invalid escrow ID");
        require(securityDeposits[_escrowId].landlord != address(0), "EscrowPayment: escrow not found");
        _;
    }

    modifier onlyEscrowParties(uint256 _escrowId) {
        require(
            msg.sender == securityDeposits[_escrowId].landlord || 
            msg.sender == securityDeposits[_escrowId].tenant,
            "EscrowPayment: not an escrow party"
        );
        _;
    }

    modifier verifiedUsers(address _landlord, address _tenant) {
        require(identityRegistry.isVerified(_landlord), "EscrowPayment: landlord not verified");
        require(identityRegistry.isVerified(_tenant), "EscrowPayment: tenant not verified");
        _;
    }

    // Security Deposit Functions

    /**
     * @dev Create security deposit escrow for a lease
     */
    function createSecurityDepositEscrow(
        uint256 _leaseId,
        address _landlord,
        address _tenant,
        address _paymentToken,
        uint256 _amount,
        uint256 _releaseDate,
        string calldata _releaseConditions,
        bytes32 _conditionsHash
    ) external 
        whenNotPaused 
        verifiedUsers(_landlord, _tenant) 
        returns (uint256) 
    {
        require(_leaseId > 0, "EscrowPayment: invalid lease ID");
        require(_amount > 0, "EscrowPayment: invalid amount");
        require(approvedTokens[_paymentToken], "EscrowPayment: token not approved");
        require(_releaseDate > block.timestamp, "EscrowPayment: invalid release date");
        require(_releaseDate <= block.timestamp + maxEscrowPeriod, "EscrowPayment: release date too far");
        require(leaseToEscrow[_leaseId] == 0, "EscrowPayment: escrow already exists for lease");

        _escrowCounter++;
        uint256 escrowId = _escrowCounter;

        securityDeposits[escrowId] = SecurityDepositEscrow({
            escrowId: escrowId,
            leaseId: _leaseId,
            landlord: _landlord,
            tenant: _tenant,
            paymentToken: _paymentToken,
            amount: _amount,
            createdAt: block.timestamp,
            releaseDate: _releaseDate,
            status: EscrowStatus.CREATED,
            releaseConditions: _releaseConditions,
            conditionsHash: _conditionsHash
        });

        leaseToEscrow[_leaseId] = escrowId;
        landlordEscrows[_landlord].push(escrowId);
        tenantEscrows[_tenant].push(escrowId);

        emit SecurityDepositCreated(escrowId, _leaseId, _tenant, _landlord, _amount);

        return escrowId;
    }

    /**
     * @dev Fund security deposit escrow
     */
    function fundSecurityDeposit(uint256 _escrowId) 
        external 
        validEscrow(_escrowId) 
        nonReentrant 
    {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(msg.sender == escrow.tenant, "EscrowPayment: only tenant can fund");
        require(escrow.status == EscrowStatus.CREATED, "EscrowPayment: escrow not in created status");

        IERC20 token = IERC20(escrow.paymentToken);
        require(token.balanceOf(msg.sender) >= escrow.amount, "EscrowPayment: insufficient balance");

        token.safeTransferFrom(msg.sender, address(this), escrow.amount);

        escrow.status = EscrowStatus.FUNDED;

        emit SecurityDepositFunded(_escrowId, msg.sender, escrow.amount);
    }

    /**
     * @dev Release security deposit
     */
    function releaseSecurityDeposit(
        uint256 _escrowId, 
        address _recipient,
        uint256 _amount,
        string calldata _reason
    ) external validEscrow(_escrowId) onlyEscrowAgent nonReentrant {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(escrow.status == EscrowStatus.FUNDED, "EscrowPayment: escrow not funded");
        require(block.timestamp >= escrow.releaseDate, "EscrowPayment: release date not reached");
        require(_amount <= escrow.amount, "EscrowPayment: amount exceeds deposit");
        require(
            _recipient == escrow.landlord || _recipient == escrow.tenant,
            "EscrowPayment: invalid recipient"
        );

        IERC20 token = IERC20(escrow.paymentToken);
        token.safeTransfer(_recipient, _amount);

        if (_amount == escrow.amount) {
            escrow.status = EscrowStatus.RELEASED;
        } else {
            // Partial release - reduce escrow amount
            escrow.amount -= _amount;
        }

        emit SecurityDepositReleased(_escrowId, _recipient, _amount, _reason);
    }

    /**
     * @dev Refund security deposit to tenant
     */
    function refundSecurityDeposit(uint256 _escrowId, string calldata _reason) 
        external 
        validEscrow(_escrowId) 
        onlyEscrowAgent 
        nonReentrant 
    {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(escrow.status == EscrowStatus.FUNDED, "EscrowPayment: escrow not funded");

        IERC20 token = IERC20(escrow.paymentToken);
        token.safeTransfer(escrow.tenant, escrow.amount);

        escrow.status = EscrowStatus.REFUNDED;

        emit SecurityDepositReleased(_escrowId, escrow.tenant, escrow.amount, _reason);
    }

    // Rent Payment Functions

    /**
     * @dev Process rent payment
     */
    function processRentPayment(
        uint256 _leaseId,
        address _landlord,
        address _tenant,
        address _paymentToken,
        uint256 _amount,
        uint256 _dueDate,
        PaymentMethod _method,
        string calldata _fiatReference,
        bytes32 _proofHash
    ) external 
        whenNotPaused 
        onlyPaymentProcessor 
        nonReentrant 
        returns (uint256) 
    {
        require(_amount > 0, "EscrowPayment: invalid amount");
        require(approvedTokens[_paymentToken], "EscrowPayment: token not approved");
        require(identityRegistry.isVerified(_landlord), "EscrowPayment: landlord not verified");
        require(identityRegistry.isVerified(_tenant), "EscrowPayment: tenant not verified");

        _paymentCounter++;
        uint256 paymentId = _paymentCounter;

        if (_method == PaymentMethod.CRYPTO) {
            IERC20 token = IERC20(_paymentToken);
            token.safeTransferFrom(_tenant, _landlord, _amount);
        }
        // For FIAT_BRIDGE and HYBRID, funds are handled by external bridge

        rentPayments[paymentId] = RentPayment({
            paymentId: paymentId,
            leaseId: _leaseId,
            landlord: _landlord,
            tenant: _tenant,
            paymentToken: _paymentToken,
            amount: _amount,
            dueDate: _dueDate,
            paidDate: block.timestamp,
            method: _method,
            fiatReference: _fiatReference,
            proofHash: _proofHash,
            isAutomated: false
        });

        emit RentPaymentProcessed(paymentId, _leaseId, _tenant, _landlord, _amount, _method);

        return paymentId;
    }

    // Automated Payment Functions

    /**
     * @dev Create automated payment subscription for rent
     */
    function createPaymentSubscription(
        uint256 _leaseId,
        address _tenant,
        address _landlord,
        address _paymentToken,
        uint256 _monthlyAmount,
        uint256 _startDate,
        uint256 _endDate
    ) external 
        whenNotPaused 
        verifiedUsers(_landlord, _tenant) 
        returns (uint256) 
    {
        require(_leaseId > 0, "EscrowPayment: invalid lease ID");
        require(_monthlyAmount > 0, "EscrowPayment: invalid amount");
        require(approvedTokens[_paymentToken], "EscrowPayment: token not approved");
        require(_startDate >= block.timestamp, "EscrowPayment: start date in past");
        require(_endDate > _startDate, "EscrowPayment: invalid subscription period");
        require(leaseToSubscription[_leaseId] == 0, "EscrowPayment: subscription already exists");

        _subscriptionCounter++;
        uint256 subscriptionId = _subscriptionCounter;

        paymentSubscriptions[subscriptionId] = PaymentSubscription({
            subscriptionId: subscriptionId,
            leaseId: _leaseId,
            tenant: _tenant,
            landlord: _landlord,
            paymentToken: _paymentToken,
            amount: _monthlyAmount,
            startDate: _startDate,
            endDate: _endDate,
            lastPayment: 0,
            nextPayment: _startDate,
            isActive: true,
            failedPayments: 0
        });

        leaseToSubscription[_leaseId] = subscriptionId;

        emit PaymentSubscriptionCreated(subscriptionId, _leaseId, _tenant, _monthlyAmount);

        return subscriptionId;
    }

    /**
     * @dev Execute automated payment
     */
    function executeAutomatedPayment(uint256 _subscriptionId) 
        public 
        onlyPaymentProcessor 
        nonReentrant 
        returns (uint256) 
    {
        PaymentSubscription storage subscription = paymentSubscriptions[_subscriptionId];
        require(subscription.isActive, "EscrowPayment: subscription not active");
        require(block.timestamp >= subscription.nextPayment, "EscrowPayment: payment not due");
        require(block.timestamp <= subscription.endDate, "EscrowPayment: subscription expired");

        IERC20 token = IERC20(subscription.paymentToken);

        // Update state before external call to prevent reentrancy
        subscription.lastPayment = block.timestamp;
        subscription.nextPayment += 30 days; // Move to next month
        subscription.failedPayments = 0; // Reset failure counter

        try token.transferFrom(subscription.tenant, subscription.landlord, subscription.amount) {
            _paymentCounter++;
            uint256 paymentId = _paymentCounter;

            rentPayments[paymentId] = RentPayment({
                paymentId: paymentId,
                leaseId: subscription.leaseId,
                landlord: subscription.landlord,
                tenant: subscription.tenant,
                paymentToken: subscription.paymentToken,
                amount: subscription.amount,
                dueDate: subscription.nextPayment,
                paidDate: block.timestamp,
                method: PaymentMethod.CRYPTO,
                fiatReference: "",
                proofHash: bytes32(0),
                isAutomated: true
            });

            emit AutomatedPaymentExecuted(_subscriptionId, paymentId, subscription.amount);
            subscription.nextPayment += 30 days; // Move to next month
            subscription.failedPayments = 0; // Reset failure counter

            emit AutomatedPaymentExecuted(_subscriptionId, paymentId, subscription.amount);
            emit RentPaymentProcessed(
                paymentId, 
                subscription.leaseId, 
                subscription.tenant, 
                subscription.landlord, 
                subscription.amount, 
                PaymentMethod.CRYPTO
            );

            return paymentId;
        } catch {
            subscription.failedPayments++;

            if (subscription.failedPayments >= maxFailedPayments) {
                subscription.isActive = false;
            }

            emit AutomatedPaymentFailed(_subscriptionId, subscription.failedPayments, "Transfer failed");

            return 0;
        }
    }

    /**
     * @dev Cancel payment subscription
     */
    function cancelPaymentSubscription(uint256 _subscriptionId) 
        external 
    {
        PaymentSubscription storage subscription = paymentSubscriptions[_subscriptionId];
        require(
            msg.sender == subscription.tenant || 
            msg.sender == subscription.landlord ||
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "EscrowPayment: not authorized to cancel"
        );

        subscription.isActive = false;
    }

    // Dispute Functions

    /**
     * @dev Raise dispute on escrow
     */
    function raiseEscrowDispute(uint256 _escrowId, string calldata _reason) 
        external 
        validEscrow(_escrowId) 
        onlyEscrowParties(_escrowId) 
    {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(escrow.status == EscrowStatus.FUNDED, "EscrowPayment: escrow not funded");

        escrow.status = EscrowStatus.DISPUTED;

        emit DisputeRaised(_escrowId, msg.sender, _reason);
    }

    /**
     * @dev Resolve escrow dispute
     */
    function resolveEscrowDispute(
        uint256 _escrowId, 
        address _recipient,
        uint256 _amount,
        string calldata _resolution
    ) external validEscrow(_escrowId) onlyDisputeResolver nonReentrant {
        SecurityDepositEscrow storage escrow = securityDeposits[_escrowId];
        require(escrow.status == EscrowStatus.DISPUTED, "EscrowPayment: not disputed");
        require(_amount <= escrow.amount, "EscrowPayment: amount exceeds deposit");
        require(
            _recipient == escrow.landlord || _recipient == escrow.tenant,
            "EscrowPayment: invalid recipient"
        );

        IERC20 token = IERC20(escrow.paymentToken);
        token.safeTransfer(_recipient, _amount);

        if (_amount == escrow.amount) {
            escrow.status = EscrowStatus.RELEASED;
        } else {
            escrow.amount -= _amount;
            escrow.status = EscrowStatus.FUNDED; // Return to funded status for remainder
        }

        emit SecurityDepositReleased(_escrowId, _recipient, _amount, _resolution);
    }

    // View Functions

    /**
     * @dev Get security deposit details
     */
    function getSecurityDeposit(uint256 _escrowId) 
        external 
        view 
        validEscrow(_escrowId) 
        returns (SecurityDepositEscrow memory) 
    {
        return securityDeposits[_escrowId];
    }

    /**
     * @dev Get rent payment details
     */
    function getRentPayment(uint256 _paymentId) 
        external 
        view 
        returns (RentPayment memory) 
    {
        require(_paymentId > 0 && _paymentId <= _paymentCounter, "EscrowPayment: invalid payment ID");
        return rentPayments[_paymentId];
    }

    /**
     * @dev Get payment subscription details
     */
    function getPaymentSubscription(uint256 _subscriptionId) 
        external 
        view 
        returns (PaymentSubscription memory) 
    {
        require(_subscriptionId > 0 && _subscriptionId <= _subscriptionCounter, 
                "EscrowPayment: invalid subscription ID");
        return paymentSubscriptions[_subscriptionId];
    }

    /**
     * @dev Get landlord's escrows
     */
    function getLandlordEscrows(address _landlord) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return landlordEscrows[_landlord];
    }

    /**
     * @dev Get tenant's escrows
     */
    function getTenantEscrows(address _tenant) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return tenantEscrows[_tenant];
    }

    /**
     * @dev Get escrow ID for lease
     */
    function getLeaseEscrow(uint256 _leaseId) 
        external 
        view 
        returns (uint256) 
    {
        return leaseToEscrow[_leaseId];
    }

    /**
     * @dev Get subscription ID for lease
     */
    function getLeaseSubscription(uint256 _leaseId) 
        external 
        view 
        returns (uint256) 
    {
        return leaseToSubscription[_leaseId];
    }

    // Administrative Functions

    /**
     * @dev Set approved payment token
     */
    function setApprovedToken(address _token, bool _approved) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        approvedTokens[_token] = _approved;
    }

    /**
     * @dev Set fiat bridge contract
     */
    function setFiatBridge(address _fiatBridge) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        fiatBridge = _fiatBridge;
    }

    /**
     * @dev Update configuration parameters
     */
    function updateConfiguration(
        uint256 _defaultEscrowPeriod,
        uint256 _maxEscrowPeriod,
        uint256 _gracePeriod,
        uint256 _maxFailedPayments
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        defaultEscrowPeriod = _defaultEscrowPeriod;
        maxEscrowPeriod = _maxEscrowPeriod;
        automatedPaymentGracePeriod = _gracePeriod;
        maxFailedPayments = _maxFailedPayments;
    }

    /**
     * @dev Emergency pause
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Unpause
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @dev Batch execute automated payments
     */
    function batchExecuteAutomatedPayments(uint256[] calldata _subscriptionIds) 
        external 
        onlyPaymentProcessor 
    {
        for (uint256 i = 0; i < _subscriptionIds.length; i++) {
            if (_subscriptionIds[i] > 0 && _subscriptionIds[i] <= _subscriptionCounter) {
                PaymentSubscription memory subscription = paymentSubscriptions[_subscriptionIds[i]];
                if (subscription.isActive && 
                    block.timestamp >= subscription.nextPayment &&
                    block.timestamp <= subscription.endDate) {
                    executeAutomatedPayment(_subscriptionIds[i]);
                }
            }
        }
    }
}

contracts/IdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/IIdentityRegistry.sol";

/**
 * @title IdentityRegistry
 * @dev Manages user identities and KYC/AML compliance status
 * Integrates with Integra's identity modules and Soulbound Tokens
 */
contract IdentityRegistry is AccessControl, ReentrancyGuard, IIdentityRegistry {

    // Roles
    bytes32 public constant IDENTITY_REGISTRAR_ROLE = keccak256("IDENTITY_REGISTRAR_ROLE");
    bytes32 public constant COMPLIANCE_OFFICER_ROLE = keccak256("COMPLIANCE_OFFICER_ROLE");

    // Identity storage structure
    struct Identity {
        address onchainID;          // Soulbound Token or identity contract address
        uint16 country;             // ISO 3166-1 numeric country code
        bool isVerified;            // KYC/AML verification status
        uint256 verificationDate;   // Timestamp of verification
        string kycProvider;         // KYC provider identifier
        bytes32 documentHash;       // Hash of KYC documents
        uint8 riskLevel;           // Risk assessment level (1-5, 1 = low risk)
        bool isActive;             // Identity status
    }

    // Storage mappings
    mapping(address => Identity) private _identities;
    mapping(address => address[]) private _boundRegistries; // For registry binding
    mapping(address => bool) private _registryBound;

    // Supported countries for compliance
    mapping(uint16 => bool) public supportedCountries;
    mapping(uint16 => bool) public restrictedCountries;

    // KYC providers
    mapping(string => bool) public approvedKYCProviders;

    // Events
    event KYCProviderAdded(string provider);
    event KYCProviderRemoved(string provider);
    event CountrySupported(uint16 indexed country, bool supported);
    event CountryRestricted(uint16 indexed country, bool restricted);
    event RiskLevelUpdated(address indexed user, uint8 newRiskLevel);

    constructor() {
        require(_grantRole(DEFAULT_ADMIN_ROLE, msg.sender), "Failed to grant DEFAULT_ADMIN_ROLE");
        require(_grantRole(IDENTITY_REGISTRAR_ROLE, msg.sender), "Failed to grant IDENTITY_REGISTRAR_ROLE");
        require(_grantRole(COMPLIANCE_OFFICER_ROLE, msg.sender), "Failed to grant COMPLIANCE_OFFICER_ROLE");

        // Add initial supported countries (examples)
        supportedCountries[840] = true; // USA
        supportedCountries[826] = true; // UK  
        supportedCountries[124] = true; // Canada
        supportedCountries[276] = true; // Germany
        supportedCountries[702] = true; // Singapore

        // Add approved KYC providers
        approvedKYCProviders["jumio"] = true;
        approvedKYCProviders["onfido"] = true;
        approvedKYCProviders["sumsub"] = true;
    }

    // Modifiers
    modifier onlyRegistrar() {
        require(hasRole(IDENTITY_REGISTRAR_ROLE, msg.sender), "IdentityRegistry: not a registrar");
        _;
    }

    modifier onlyComplianceOfficer() {
        require(hasRole(COMPLIANCE_OFFICER_ROLE, msg.sender), "IdentityRegistry: not a compliance officer");
        _;
    }

    modifier validCountry(uint16 _country) {
        require(supportedCountries[_country], "IdentityRegistry: country not supported");
        require(!restrictedCountries[_country], "IdentityRegistry: country restricted");
        _;
    }

    // Core Identity Functions

    /**
     * @dev Register a new identity with KYC verification
     */
    function registerIdentity(
        address _userAddress,
        address _identity,
        uint16 _country
    ) external override onlyRegistrar validCountry(_country) nonReentrant {
        require(_userAddress != address(0), "IdentityRegistry: invalid user address");
        require(_identity != address(0), "IdentityRegistry: invalid identity address");
        require(!_identities[_userAddress].isActive, "IdentityRegistry: identity already exists");

        _identities[_userAddress] = Identity({
            onchainID: _identity,
            country: _country,
            isVerified: false, // Will be set to true after KYC completion
            verificationDate: 0,
            kycProvider: "",
            documentHash: bytes32(0),
            riskLevel: 3, // Default medium risk
            isActive: true
        });

        emit IdentityStored(_userAddress, _identity);
    }

    /**
     * @dev Complete KYC verification for a user
     */
    function completeKYCVerification(
        address _userAddress,
        string calldata _kycProvider,
        bytes32 _documentHash,
        uint8 _riskLevel
    ) external onlyComplianceOfficer {
        require(_identities[_userAddress].isActive, "IdentityRegistry: identity not found");
        require(approvedKYCProviders[_kycProvider], "IdentityRegistry: KYC provider not approved");
        require(_riskLevel >= 1 && _riskLevel <= 5, "IdentityRegistry: invalid risk level");

        _identities[_userAddress].isVerified = true;
        _identities[_userAddress].verificationDate = block.timestamp;
        _identities[_userAddress].kycProvider = _kycProvider;
        _identities[_userAddress].documentHash = _documentHash;
        _identities[_userAddress].riskLevel = _riskLevel;

        emit IdentityModified(_identities[_userAddress].onchainID, _identities[_userAddress].onchainID);
    }

    /**
     * @dev Delete an identity
     */
    function deleteIdentity(address _userAddress) 
        external 
        override 
        onlyRegistrar 
        nonReentrant 
    {
        require(_identities[_userAddress].isActive, "IdentityRegistry: identity not found");

        address oldIdentity = _identities[_userAddress].onchainID;
        delete _identities[_userAddress];

        emit IdentityUnstored(_userAddress, oldIdentity);
    }

    /**
     * @dev Update identity address (for recovery or migration)
     */
    function updateIdentity(address _userAddress, address _identity) 
        external 
        override 
        onlyRegistrar 
    {
        require(_identities[_userAddress].isActive, "IdentityRegistry: identity not found");
        require(_identity != address(0), "IdentityRegistry: invalid identity address");

        address oldIdentity = _identities[_userAddress].onchainID;
        _identities[_userAddress].onchainID = _identity;

        emit IdentityModified(oldIdentity, _identity);
    }

    /**
     * @dev Update user's country
     */
    function updateCountry(address _userAddress, uint16 _country) 
        external 
        override 
        onlyComplianceOfficer 
        validCountry(_country) 
    {
        require(_identities[_userAddress].isActive, "IdentityRegistry: identity not found");

        _identities[_userAddress].country = _country;
        emit CountryModified(_userAddress, _country);
    }

    /**
     * @dev Update user's risk level
     */
    function updateRiskLevel(address _userAddress, uint8 _riskLevel) 
        external 
        onlyComplianceOfficer 
    {
        require(_identities[_userAddress].isActive, "IdentityRegistry: identity not found");
        require(_riskLevel >= 1 && _riskLevel <= 5, "IdentityRegistry: invalid risk level");

        _identities[_userAddress].riskLevel = _riskLevel;
        emit RiskLevelUpdated(_userAddress, _riskLevel);
    }

    // Getter Functions

    /**
     * @dev Get identity address for a user
     */
    function identity(address _userAddress) 
        external 
        view 
        override 
        returns (address) 
    {
        return _identities[_userAddress].onchainID;
    }

    /**
     * @dev Get investor country
     */
    function investorCountry(address _userAddress) 
        external 
        view 
        override 
        returns (uint16) 
    {
        return _identities[_userAddress].country;
    }

    /**
     * @dev Check if user is verified
     */
    function isVerified(address _userAddress) 
        external 
        view 
        override 
        returns (bool) 
    {
        return _identities[_userAddress].isVerified && _identities[_userAddress].isActive;
    }

    /**
     * @dev Check if identity exists
     */
    function contains(address _userAddress) 
        external 
        view 
        override 
        returns (bool) 
    {
        return _identities[_userAddress].isActive;
    }

    /**
     * @dev Get complete identity information
     */
    function getIdentityDetails(address _userAddress) 
        external 
        view 
        returns (
            address onchainID,
            uint16 country,
            bool verified,
            uint256 verificationDate,
            string memory kycProvider,
            uint8 riskLevel,
            bool isActive
        ) 
    {
        Identity memory userIdentity = _identities[_userAddress];
        return (
            userIdentity.onchainID,
            userIdentity.country,
            userIdentity.isVerified,
            userIdentity.verificationDate,
            userIdentity.kycProvider,
            userIdentity.riskLevel,
            userIdentity.isActive
        );
    }

    /**
     * @dev Get user's risk level
     */
    function getRiskLevel(address _userAddress) external view returns (uint8) {
        return _identities[_userAddress].riskLevel;
    }

    // Batch Operations

    /**
     * @dev Register multiple identities at once
     */
    function batchRegisterIdentity(
        address[] calldata _userAddresses,
        address[] calldata _onchainIDs,
        uint16[] calldata _countries
    ) external override onlyRegistrar nonReentrant {
        require(
            _userAddresses.length == _onchainIDs.length && 
            _onchainIDs.length == _countries.length,
            "IdentityRegistry: arrays length mismatch"
        );

        for (uint256 i = 0; i < _userAddresses.length; i++) {
            if (supportedCountries[_countries[i]] && !restrictedCountries[_countries[i]]) {
                this.registerIdentity(_userAddresses[i], _onchainIDs[i], _countries[i]);
            }
        }
    }

    // Registry Binding (for integration with other contracts)

    /**
     * @dev Bind to another identity registry
     */
    function bindIdentityRegistry(address _identityRegistry) 
        external 
        override 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        require(_identityRegistry != address(0), "IdentityRegistry: invalid registry address");
        require(!_registryBound[_identityRegistry], "IdentityRegistry: registry already bound");

        _boundRegistries[msg.sender].push(_identityRegistry);
        _registryBound[_identityRegistry] = true;

        emit IdentityRegistryBound(_identityRegistry);
    }

    /**
     * @dev Unbind from another identity registry
     */
    function unbindIdentityRegistry(address _identityRegistry) 
        external 
        override 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        require(_registryBound[_identityRegistry], "IdentityRegistry: registry not bound");

        _registryBound[_identityRegistry] = false;

        // Remove from array
        address[] storage registries = _boundRegistries[msg.sender];
        for (uint256 i = 0; i < registries.length; i++) {
            if (registries[i] == _identityRegistry) {
                registries[i] = registries[registries.length - 1];
                registries.pop();
                break;
            }
        }

        emit IdentityRegistryUnbound(_identityRegistry);
    }

    // Admin Functions

    /**
     * @dev Add supported country
     */
    function setSupportedCountry(uint16 _country, bool _supported) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        supportedCountries[_country] = _supported;
        emit CountrySupported(_country, _supported);
    }

    /**
     * @dev Set country restriction
     */
    function setRestrictedCountry(uint16 _country, bool _restricted) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        restrictedCountries[_country] = _restricted;
        emit CountryRestricted(_country, _restricted);
    }

    /**
     * @dev Add approved KYC provider
     */
    function addKYCProvider(string calldata _provider) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        approvedKYCProviders[_provider] = true;
        emit KYCProviderAdded(_provider);
    }

    /**
     * @dev Remove KYC provider
     */
    function removeKYCProvider(string calldata _provider) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        approvedKYCProviders[_provider] = false;
        emit KYCProviderRemoved(_provider);
    }

    /**
     * @dev Emergency suspend identity
     */
    function suspendIdentity(address _userAddress) 
        external 
        onlyComplianceOfficer 
    {
        require(_identities[_userAddress].isActive, "IdentityRegistry: identity not found");
        _identities[_userAddress].isVerified = false;

        emit IdentityModified(_identities[_userAddress].onchainID, address(0));
    }

    /**
     * @dev Reactivate suspended identity
     */
    function reactivateIdentity(address _userAddress) 
        external 
        onlyComplianceOfficer 
    {
        require(_identities[_userAddress].isActive, "IdentityRegistry: identity not found");
        require(_identities[_userAddress].verificationDate > 0, "IdentityRegistry: never verified");

        _identities[_userAddress].isVerified = true;

        emit IdentityModified(address(0), _identities[_userAddress].onchainID);
    }
}

